def simulate_sequences(A, B, C, D, a1, N=50):
    # f(x) = Ax + B
    # g(x) = Cx + D

    a = [a1]
    b = []

    for n in range(N):
        a_n = a[-1]
        b_n = A * a_n + B
        b.append(b_n)

        if n < N - 1:
            a_n_plus_1 = C * b_n + D
            a.append(a_n_plus_1)

    return a, b

def check_condition_1(A, B, C, D, a1, N=50, primes=[3, 5, 7]):
    a, b = simulate_sequences(A, B, C, D, a1, N)

    print(f"--- Testing f(x) = {A}x + {B}, g(x) = {C}x + {D} ---")
    print(f"Sequence lengths: a_n={len(a)}, b_n={len(b)}")

    all_divisible = True
    for k in primes:
        found_divisible = False
        # Check a_n
        for val in a:
            if val != 0 and val % k == 0:
                found_divisible = True
                break
        if not found_divisible:
            # Check b_n
            for val in b:
                if val != 0 and val % k == 0:
                    found_divisible = True
                    break

        if not found_divisible:
            print(f"FAILURE: For k={k}, no term in a_n or b_n is divisible by {k} within {N} terms.")
            all_divisible = False

    if all_divisible:
        print("SUCCESS: All tested primes ({}, {}) resulted in at least one divisible term.".format(primes))
    return all_divisible

# Test Case: A=1, C=2 (f(0)-g(0) = 7975)
check_condition_1(A=1, B=10000, C=2, D=2025, a1=2024, N=50, primes=[3, 5, 7])
